
CREATE DATABASE base_empleados;

use base_empleados;

create table empleados(
	leg INT PRIMARY KEY NOT NULL auto_increment,
    apellido VARCHAR(100),
    nombre VARCHAR(100),
    fecha_alta DATE,
    area_general VARCHAR(100),
    centro_De_costo VARCHAR(100),
    equipo_principal VARCHAR(100),
    gerente_a_cargo VARCHAR(100),
    responsable_desarrollo VARCHAR(100),
    area VARCHAR(100),
    categoria VARCHAR(100),
    nivel VARCHAR(100),
    puesto VARCHAR(100),
    fecha_de_baja  DATE default null,
    genero VARCHAR(100),
    turno VARCHAR(100),
    convenio VARCHAR(100),
    sucursal VARCHAR(100),
    zona_laboral VARCHAR(100),
    sueldo INT
);

/*
-- Query: SELECT * FROM empleados
LIMIT 0, 2000

-- Date: 2025-03-10 23:39
*/





/*mostrar los empleados que ingresaron entre el 2001 y el 2009*/
SELECT * FROM EMPLEADOS 
WHERE fecha_alta >= '2001-01-01' AND fecha_alta <= '2009-12-30'
ORDER BY fecha_alta;


/*mostrar los empleados donde el area general sea solo de recursos humanos*/
SELECT * FROM EMPLEADOS 
WHERE area_general = 'RECURSOS HUMANOS';


/*mostrar los empleados donde el gerente a cargo sea Lionel Messi*/
SELECT * FROM EMPLEADOS 
WHERE gerente_a_cargo = 'Esteban Quito';

/*mostrar todos los ex-empleados */
SELECT * FROM EMPLEADOS WHERE fecha_de_baja is not null;

/*mostrar el total de empleados por area */
SELECT COUNT(area) as total , area 
FROM EMPLEADOS 
GROUP BY AREA
ORDER BY total DESC;

/*mostrar el total y porcentaje de empleados por señority */
SELECT COUNT(categoria) as total , 
       CONCAT(ROUND((COUNT(categoria)*100)/(SELECT count(*) FROM EMPLEADOS),2), ' %') AS  porcentaje, 
        categoria 
FROM EMPLEADOS 
GROUP BY categoria
ORDER BY total DESC;
